factorial.code:
MODULE Factorial;

FROM InOut IMPORT WriteCard, WriteLn;

PROCEDURE Fact(n: CARDINAL): CARDINAL;
BEGIN
  IF n <= 1 THEN
    RETURN 1
  ELSE
    RETURN n * Fact(n - 1)
  END
END Fact;

BEGIN
  WriteCard(Fact(10), 0);
  WriteLn
END Factorial.

fizzbuzz.code:
MODULE FizzBuzz;

FROM InOut IMPORT WriteString, WriteCard, WriteLn;

VAR i: CARDINAL;

BEGIN
  FOR i := 1 TO 15 DO
    IF i MOD 15 = 0 THEN WriteString("FizzBuzz")
    ELSIF i MOD 3 = 0 THEN WriteString("Fizz")
    ELSIF i MOD 5 = 0 THEN WriteString("Buzz")
    ELSE WriteCard(i, 0)
    END;
    WriteLn
  END
END FizzBuzz.

higher-order.code:
MODULE MapFilter;
FROM InOut IMPORT Write, WriteCard, WriteLn;

TYPE
  Predicate = PROCEDURE (CARDINAL): BOOLEAN;   (* procedure types *)
  Mapping   = PROCEDURE (CARDINAL): CARDINAL;

PROCEDURE IsEven(x: CARDINAL): BOOLEAN; BEGIN RETURN NOT ODD(x) END IsEven;
PROCEDURE Square(x: CARDINAL): CARDINAL; BEGIN RETURN x * x END Square;

(* An open array parameter accepts any length; HIGH gives the last index. *)
PROCEDURE FilterMap(VAR a: ARRAY OF CARDINAL; keep: Predicate; f: Mapping);
  VAR i: CARDINAL; first: BOOLEAN;
BEGIN
  first := TRUE;
  FOR i := 0 TO HIGH(a) DO
    IF keep(a[i]) THEN
      IF NOT first THEN Write(" ") END;
      WriteCard(f(a[i]), 0);
      first := FALSE
    END
  END;
  WriteLn
END FilterMap;

VAR xs: ARRAY [1..10] OF CARDINAL; i: CARDINAL;
BEGIN
  FOR i := 1 TO 10 DO xs[i] := i END;
  FilterMap(xs, IsEven, Square)
END MapFilter.

shapes.code:
MODULE Shapes;
FROM InOut IMPORT WriteString, WriteCard, WriteLn;

TYPE
  Kind = (Rectangle, Triangle);
  Shape = RECORD
    CASE kind: Kind OF                 (* variant record, as in Pascal *)
      Rectangle: width, height: CARDINAL
    | Triangle:  base, altitude: CARDINAL
    END
  END;

PROCEDURE Area(s: Shape): CARDINAL;
BEGIN
  CASE s.kind OF
    Rectangle: RETURN s.width * s.height
  | Triangle:  RETURN s.base * s.altitude DIV 2
  END
END Area;

PROCEDURE Show(name: ARRAY OF CHAR; s: Shape);
BEGIN
  WriteString(name); WriteString(": "); WriteCard(Area(s), 0); WriteLn
END Show;

VAR r, t: Shape;
BEGIN
  r.kind := Rectangle; r.width := 3; r.height := 4;
  t.kind := Triangle;  t.base := 10; t.altitude := 3;
  Show("Rectangle", r); Show("Triangle", t)
END Shapes.

signature.code:
MODULE Modules;
FROM InOut IMPORT WriteString, WriteCard, WriteLn;

  MODULE Stack;                      (* a local module: a wall around its data *)
    EXPORT Push, Pop, Empty;         (* only these names are visible outside *)
    VAR items: ARRAY [1..16] OF CARDINAL;
        top: CARDINAL;

    PROCEDURE Push(x: CARDINAL); BEGIN INC(top); items[top] := x END Push;
    PROCEDURE Pop(): CARDINAL; BEGIN DEC(top); RETURN items[top + 1] END Pop;
    PROCEDURE Empty(): BOOLEAN; BEGIN RETURN top = 0 END Empty;
  BEGIN
    top := 0                         (* module initialisation runs first *)
  END Stack;

VAR i: CARDINAL;
BEGIN
  FOR i := 1 TO 5 DO Push(i * i) END;
  (* 'items' and 'top' are out of scope here; only the exports are usable *)
  WriteCard(Pop(), 0);
  WHILE NOT Empty() DO WriteString(" "); WriteCard(Pop(), 0) END;
  WriteLn
END Modules.
